/*
	 * Use trylock to avoid a potential circular locking dependency
	 * between ns_sem and other locks such as the DAT file's mi_sem
	 * (dat_lock_key).  If the lock cannot be acquired, the error
	 * flag will not be set on the superblock, but the error message
	 * has already been printed and the filesystem will be remounted
	 * read-only if the ERRORS_RO mount option is set.
	 */
	if (!down_write_trylock(&nilfs->ns_sem))
		return;
